SELECT COUNT(DISTINCT c.id) FROM customer c LEFT JOIN customer_label cl ON c.id = cl.customer_id LEFT JOIN label l ON cl.label_id = l.id WHERE 1=1
AND ( c.company_name LIKE CONCAT('%', #{keyword}, '%') OR c.contact_person LIKE CONCAT('%', #{keyword}, '%') OR l.name LIKE CONCAT('%', #{keyword}, '%') )
AND c.industry = #{industry}
AND c.employee_scale = #{employeeScale}

SELECT c.id FROM customer c LEFT JOIN customer_label cl ON c.id = cl.customer_id LEFT JOIN label l ON cl.label_id = l.id WHERE 1=1
AND ( c.company_name LIKE CONCAT('%', #{keyword}, '%') OR c.contact_person LIKE CONCAT('%', #{keyword}, '%') OR l.name LIKE CONCAT('%', #{keyword}, '%') )
AND c.industry = #{industry}
AND c.employee_scale = #{employeeScale}
GROUP BY c.id ORDER BY MAX(c.create_time) DESC LIMIT #{offset}, #{limit}
